#!/usr/bin/env node
// Keeps ios/TikiAcca/Supporting/Expo.plist's EXUpdatesRuntimeVersion in sync
// with app.json's expo.version.
//
// The native iOS project is committed to git rather than regenerated by
// `expo prebuild`, so app.json's `runtimeVersion.policy: "appVersion"` never
// gets re-applied on its own — without this, bumping app.json's version and
// forgetting to update the plist makes `eas update` OTA pushes silently stop
// reaching devices (mismatched runtime version, no error).
//
// Runs automatically on every EAS build via the eas-build-post-install hook
// (see package.json), so nobody needs to remember to touch the plist by hand.

const fs = require("node:fs");
const path = require("node:path");

const appJsonPath = path.join(__dirname, "..", "app.json");
const plistPath = path.join(
  __dirname,
  "..",
  "ios",
  "TikiAcca",
  "Supporting",
  "Expo.plist"
);

if (!fs.existsSync(plistPath)) {
  // No committed iOS project (e.g. an Android-only build) — nothing to sync.
  process.exit(0);
}

const { expo } = JSON.parse(fs.readFileSync(appJsonPath, "utf8"));
const version = expo.version;

const plist = fs.readFileSync(plistPath, "utf8");
const pattern = /(<key>EXUpdatesRuntimeVersion<\/key>\s*<string>)[^<]*(<\/string>)/;

if (!pattern.test(plist)) {
  console.error("EXUpdatesRuntimeVersion key not found in Expo.plist — check expo-updates is still configured.");
  process.exit(1);
}

const updated = plist.replace(pattern, `$1${version}$2`);

if (updated !== plist) {
  fs.writeFileSync(plistPath, updated);
  console.log(`Synced EXUpdatesRuntimeVersion -> ${version}`);
} else {
  console.log(`EXUpdatesRuntimeVersion already ${version}`);
}
